package com.combodetector.core;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

/** Formats and writes the combo-detector output file. */
public final class OutputWriter {

    private OutputWriter() {
    }

    public static void write(Path outputFile, List<ComboProcessor.Recognition> log, Map<String, Integer> tally)
        throws IOException {
        StringBuilder sb = new StringBuilder();

        for (ComboProcessor.Recognition r : log) {
            sb.append("TICK ").append(r.tick).append(' ').append(r.name).append('\n');
        }

        sb.append("--- TALLY ---\n");
        sb.append("HADOKEN ").append(tally.getOrDefault("HADOKEN", 0)).append('\n');
        sb.append("SHORYUKEN ").append(tally.getOrDefault("SHORYUKEN", 0)).append('\n');
        sb.append("TATSU ").append(tally.getOrDefault("TATSU", 0)).append('\n');
        sb.append("TOTAL ").append(log.size()).append('\n');

        Path parent = outputFile.toAbsolutePath().getParent();
        if (parent != null) {
            Files.createDirectories(parent);
        }
        Files.write(outputFile, sb.toString().getBytes(StandardCharsets.UTF_8));
    }
}

package com.combodetector.core;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.InputMultiplexer;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

/**
 * Wires together the {@link TimelineParser}, {@link TimelineMockInput}, {@link PauseProcessor} and
 * {@link ComboProcessor} to replay an input timeline file and collect the recognized combos.
 */
public final class ComboDetectorRunner {

    /** Result of a full timeline replay: chronological combo log plus final tally. */
    public static final class Result {
        public final List<ComboProcessor.Recognition> log;
        public final Map<String, Integer> tally;

        Result(List<ComboProcessor.Recognition> log, Map<String, Integer> tally) {
            this.log = log;
            this.tally = tally;
        }
    }

    private ComboDetectorRunner() {
    }

    public static Result run(Path inputFile) throws IOException {
        List<List<TimelineMockInput.Event>> ticks = TimelineParser.parse(inputFile);

        PauseProcessor pauseProcessor = new PauseProcessor();
        ComboProcessor comboProcessor = new ComboProcessor();
        InputMultiplexer multiplexer = new InputMultiplexer(pauseProcessor, comboProcessor);

        TimelineMockInput input = new TimelineMockInput(ticks);
        input.setInputProcessor(multiplexer);

        // Make this the application's actual input source, as a real libGDX game would use Gdx.input.
        Gdx.input = input;

        input.replay(comboProcessor::setCurrentTick);

        return new Result(comboProcessor.getLog(), comboProcessor.getTally());
    }
}

package com.combodetector.headless;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Entry point. Boots a real {@link HeadlessApplication} (no graphics/audio/OpenGL) whose single
 * {@code create()} call replays the recorded input timeline and writes the combo report.
 *
 * <p>Usage: {@code headless <input_file> <output_file>}
 */
public final class Main {

    private Main() {
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.err.println("Usage: headless <input_file> <output_file>");
            System.exit(1);
            return;
        }

        Path inputFile = Paths.get(args[0]);
        Path outputFile = Paths.get(args[1]);

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // Negative: HeadlessApplication never calls render() / enters its loop. All work happens
        // once, synchronously, inside create() below, before the (non-daemon) app thread exits.
        config.updatesPerSecond = -1;

        new HeadlessApplication(new ComboDetectorApplication(inputFile, outputFile), config);
    }
}

package com.combodetector.headless;

import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;
import com.combodetector.core.ComboDetectorRunner;
import com.combodetector.core.OutputWriter;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Path;

/**
 * The one and only {@link ApplicationListener} for this app. All real work happens once, inside
 * {@link #create()}: parse the timeline, replay it through the multiplexer, write the report, exit.
 */
public class ComboDetectorApplication implements ApplicationListener {

    private final Path inputFile;
    private final Path outputFile;

    public ComboDetectorApplication(Path inputFile, Path outputFile) {
        this.inputFile = inputFile;
        this.outputFile = outputFile;
    }

    @Override
    public void create() {
        try {
            ComboDetectorRunner.Result result = ComboDetectorRunner.run(inputFile);
            OutputWriter.write(outputFile, result.log, result.tally);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } finally {
            Gdx.app.exit();
        }
    }

    @Override
    public void resize(int width, int height) {
        // no-op: headless, no window to resize
    }

    @Override
    public void render() {
        // no-op: not called, updatesPerSecond is negative
    }

    @Override
    public void pause() {
        // no-op
    }

    @Override
    public void resume() {
        // no-op
    }

    @Override
    public void dispose() {
        // no-op
    }
}
